// Opaque cursor format: "cN" where N is a non-negative integer with no
// leading zeros. The first page (no cursor) returns next_cursor "c0"; each
// subsequent page returns the next value ("c1", "c2", ...).
// A cursor "cN" fetches page (N+1) at offset (N+1)*limit.
const CURSOR_RE = /^c(?:0|[1-9]\d*)$/;
const ALLOWED_ARGS = new Set(['limit', 'cursor']);

export async function listTools() {
  return [
    {
      name: 'audit_page',
      description:
        'Return a page of audit records with opaque cursor-based pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          limit: { type: 'integer', minimum: 1, maximum: 3 },
          cursor: { type: 'string' }
        },
        required: ['limit'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'audit_page') {
    const err = new Error(`Unknown tool: ${name}`);
    err.code = -32601;
    throw err;
  }

  for (const key of Object.keys(args)) {
    if (!ALLOWED_ARGS.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  const { limit, cursor } = args;

  if (limit === undefined || limit === null) {
    throw new Error('limit is required');
  }
  if (!Number.isInteger(limit) || limit < 1 || limit > 3) {
    throw new Error('limit must be an integer between 1 and 3');
  }

  let page = 0;
  if (cursor !== undefined && cursor !== null) {
    if (typeof cursor !== 'string' || !CURSOR_RE.test(cursor)) {
      throw new Error('Invalid cursor');
    }
    page = Number(cursor.slice(1)) + 1;
  }

  const offset = page * limit;
  if (offset >= records.length) {
    throw new Error('Invalid cursor');
  }

  const pageRecords = records.slice(offset, offset + limit);
  const hasMore = offset + pageRecords.length < records.length;
  const nextCursor = hasMore ? `c${page}` : null;

  return {
    content: [
      {
        type: 'text',
        text: JSON.stringify({ records: pageRecords, next_cursor: nextCursor })
      }
    ]
  };
}
"}

