{"command": "node -e '
import("./server.mjs").then(async ({callTool, listTools}) => {
  const t = (a) => JSON.parse((a).content[0].text);
  // Page 1
  let p1 = t(await callTool("audit_page", {limit:2}));
  console.log("p1:", JSON.stringify(p1));
  // Page 2 via c0
  let p2 = t(await callTool("audit_page", {limit:2, cursor:p1.next_cursor}));
  console.log("p2:", JSON.stringify(p2));
  // Beyond end
  try { await callTool("audit_page", {limit:2, cursor:p2.next_cursor}); console.log("FAIL: no error past end"); }
  catch(e){ console.log("past-end err:", e.message); }
  // Malformed cursor
  try { await callTool("audit_page", {limit:2, cursor:"x9"}); console.log("FAIL: malformed ok"); }
  catch(e){ console.log("malformed err:", e.message); }
  // Invalid limit
  try { await callTool("audit_page", {limit:0}); console.log("FAIL: limit0 ok"); }
  catch(e){ console.log("limit0 err:", e.message); }
  try { await callTool("audit_page", {limit:4}); console.log("FAIL: limit4 ok"); }
  catch(e){ console.log("limit4 err:", e.message); }
  // Missing limit
  try { await callTool("audit_page", {}); console.log("FAIL: nolimit ok"); }
  catch(e){ console.log("nolimit err:", e.message); }
  // Extra field
  try { await callTool("audit_page", {limit:2, foo:1}); console.log("FAIL: extra ok"); }
  catch(e){ console.log("extra err:", e.message); }
  // Unknown tool
  try { await callTool("nope", {limit:2}); console.log("FAIL: unknowntool ok"); }
  catch(e){ console.log("unknowntool err:", e.message); }
  // listTools
  console.log("tools:", JSON.stringify(await listTools()));
});
'"}

